// src/api/bomAPI.js
import axios_api from "./axios";
import { apiPath } from "./config";

// 공통 호스트(데모면 /<FRONT_BASE>/plan/bom, 운영이면 <BASE_URL>/plan/bom)
const host = apiPath("/plan/bom");

// 목록
export const getBomList = async () => {
  const res = await axios_api.get(host);
  return res.data;
};

// 단건
export const getBomOne = async (bomId) => {
  if (bomId == null) throw new Error("bomId 누락");
  const res = await axios_api.get(apiPath(`/plan/bom/${bomId}`));
  return res.data;
};

// 등록
export const createBom = async (formData) => {
  const payload = {
    itemNo: Number(formData.itemNo),
    partNo: Number(formData.partNo),
    qtyPerItem: Number(formData.qtyPerItem),
  };
  const res = await axios_api.post(host, payload);
  return res.data;
};

// 수정
export const updateBom = async (formData) => {
  const { bomId, itemNo, partNo, qtyPerItem } = formData || {};
  if (bomId == null) throw new Error("bomId 누락");
  const payload = {
    itemNo: Number(itemNo),
    partNo: Number(partNo),
    qtyPerItem: Number(qtyPerItem),
  };
  const res = await axios_api.put(apiPath(`/plan/bom/${bomId}`), payload);
  return res.data;
};

// 삭제
export const deleteBom = async (bomId) => {
  if (bomId == null) throw new Error("bomId 누락");
  const res = await axios_api.delete(apiPath(`/plan/bom/${bomId}`));
  return res.data;
};
